'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const safeGet=k=>{try{return localStorage.getItem(k)}catch{return null}},safeSet=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
if(safeGet('dort-theme')==='dark')document.body.classList.add('dark');
$('#theme').onclick=()=>{document.body.classList.toggle('dark');safeSet('dort-theme',document.body.classList.contains('dark')?'dark':'light')};
function menu(open){$('#toc').classList.toggle('open',open);$('#toc').inert=!open;$('#shade').hidden=!open;$('#menu').setAttribute('aria-expanded',String(open));if(open)$('#closeMenu').focus();else $('#menu').focus()}
$('#menu').onclick=()=>menu(!$('#toc').classList.contains('open'));$('#closeMenu').onclick=()=>menu(false);$('#shade').onclick=()=>menu(false);document.addEventListener('keydown',e=>{if(e.key==='Escape')menu(false);if(e.key==='Tab'&&$('#toc').classList.contains('open')){const f=$$('#toc button,#toc input,#toc a');if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});$$('#toc a').forEach(a=>a.onclick=()=>{clearSearch();menu(false)});
$('#print').onclick=()=>{const q=$$('.original');const states=q.map(x=>x.open);q.forEach(x=>x.open=true);window.print();q.forEach((x,i)=>x.open=states[i])};
$('#expandAll').onclick=()=>$$('.original').forEach(d=>d.open=true);$('#collapseAll').onclick=()=>$$('.original').forEach(d=>d.open=false);
function clearSearch(){$('#search').value='';$$('.searchable').forEach(x=>x.hidden=false);$('#searchStatus').textContent=''}
$('#search').oninput=e=>{const q=e.target.value.trim().toLowerCase();let n=0;$$('.searchable').forEach(x=>{const hit=!q||(x.id+' '+x.textContent).toLowerCase().includes(q);x.hidden=!hit;if(hit)n++});$('#searchStatus').textContent=q?`找到 ${n} 项；清空搜索恢复全部条文。`:''};
const flash=[['多特为什么从“全人类都该定罪”开始？','使恩典在真实罪责中被认识：神不欠罪人救恩；他施救出于怜悯。I.1–5。'],['拣选以信心为前提，还是生出信心？','不是因预见信心而选；在基督里的拣选生出信心、圣洁与最终荣耀。I.7–9。'],['基督代赎的价值、对象、宣讲应如何区分？','价值无限；实际救赎蒙选者；凡信者必得救的福音要无分别宣告。II.3–5、8。'],['有效恩典是不是把人当木石？','不是。圣灵更新意志，使原本不愿的人成为甘心、真实相信的人。III/IV.12、16。'],['自然知识与律法能不能使罪人重生？','不能。两者显明责任与罪，却不能产生救恩；圣灵藉福音使人活。III/IV.4–6。'],['缺乏强烈确据，能断言自己被弃绝吗？','不能。I.16鼓励忧伤寻求者继续使用蒙恩途径；V.11承认确据的争战。'],['I.17究竟安慰谁？','敬虔父母面对神在婴孩时期接走的儿女；不可扩成对所有婴孩命运的普遍定义。'],['神保守我，还要读经、听道与守圣礼吗？','要。神使用圣道、劝勉、警告、应许与圣礼来保守人。V.14。'],['为什么有三项联合信条？','比利时公开认信，海德堡长期教导，多特裁断争议；共同服务同一圣经信仰。'],['三一神论与多特有什么关系？','父、子、圣灵同为一位真神，救恩工作不可分割；基督真神真人，代赎才有所需的无限价值。'],['保守与坚忍是什么关系？','神信实保守，信徒因此实际坚忍；不是不信不悔改仍可凭过去经历自保。'],['结语要求我们如何辩论？','按公开信条与经文理解对方，不凭脱离语境的语句诬蔑；教导应敬虔、审慎并顾念听众。']];let fi=0;
function showCard(){const [q,a]=flash[fi];$('#cardno').textContent=`RECALL ${String(fi+1).padStart(2,'0')} / ${flash.length}`;$('#question').textContent=q;$('#answer').textContent=a;$('#answer').hidden=true}
function flip(){$('#answer').hidden=!$('#answer').hidden}$('#flashcard').onclick=flip;$('#flashcard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();flip()}};$('#next').onclick=()=>{fi=(fi+1)%flash.length;showCard()};$('#prev').onclick=()=>{fi=(fi+flash.length-1)%flash.length;showCard()};showCard();
for(let i=1;i<=7;i++){const l=document.createElement('label');l.className='check';const c=document.createElement('input');c.type='checkbox';c.checked=safeGet('dort-day'+i)==='1';c.onchange=()=>safeSet('dort-day'+i,c.checked?'1':'0');l.append(c,document.createTextNode(`第${i}日已读`));$('#checklist').append(l)}
$('#personalNotes').value=safeGet('dort-notes')||'';$('#personalNotes').oninput=e=>safeSet('dort-notes',e.target.value);$('#exportNotes').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['多特信经学习笔记\n'+new Date().toLocaleString('zh-CN',{timeZone:'Asia/Taipei'})+'\n\n'+$('#personalNotes').value],{type:'text/plain;charset=utf-8'}));a.download='多特信经-我的学习笔记.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
